{
  "name": "@amykit/workflow-note-to-plan",
  "version": "0.7.1",
  "description": "The note-to-plan workflow: friction becomes a plan in the repository it is about.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "examples/workflow-note-to-plan"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "workflow.mmd"
  ],
  "dependencies": {
    "@amykit/core": "^0.7.1",
    "@amykit/plugin-file-queue": "^0.7.1",
    "@amykit/workflow-pull-request": "^0.7.1",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0",
    "@amykit/workflow-testkit": "^0.7.1"
  }
}

import {
  ActionContext,
  baseBranchFor,
  Moved,
  RepoLayout,
  Store,
  WorkflowActionScope,
  WorkflowPieceContext,
  unitOf,
} from "@amykit/core";
import type { PullRequestInput } from "@amykit/workflow-pull-request";
import type { Effect } from "./decide.js";
import { Observation, Policy } from "./observation.js";
import { EffectOutcomes, applyOutcomes } from "./outcomes.js";
import { PlanRecord } from "./record.js";
import { Note } from "./ports/Notes.js";
import type { configSchema, needs } from "./plugin.js";
import { branchFor, pullRequestBody, pullRequestTitle, slugFor } from "./plan-file.js";
import { draftPrompt } from "./prompt.js";

/**
 * What the declaration hands every piece. Everything here names a note, a
 * plan file or a repository; what drives it is the same engine that drives
 * the ticket workflow, which had to learn nothing to do it.
 */
type Scope = WorkflowPieceContext<typeof configSchema, Policy, typeof needs>;
type ActionScope = WorkflowActionScope<typeof configSchema, Policy, typeof needs>;
type Work = ActionContext<PlanRecord, Observation>;

/** States where a plan is on its way to a pull request, or already is one. */
const IN_FLIGHT = ["DRAFTED", "CHECKED", "PR_OPEN"];

/** Every note somebody wrote down, except the machine's reports on itself. */
export async function discover(scope: Scope): Promise<string[]> {
  return scope.ports.notes.all().filter(plannable).map((note) => note.id);
}

export async function observe(scope: Scope, current: PlanRecord): Promise<Observation> {
  const note = scope.ports.notes.get(unitOf(current));
  if (!note) throw new Error(`the note ${unitOf(current)} is not in the notes directory any more`);

  return {
    note,
    writable: scope.config.repos.includes(note.repo),
    plansInFlight: inFlightFor(scope.ports.store, note.repo, current.id),
    now: scope.ctx.now(),
  };
}

/**
 * The agent writes the plan on its own branch, through the same mounted port
 * the ticket workflow reaches for `triage` and `implement` — which is what
 * puts these prompts on the same ladder and under the same ceiling.
 */
export async function draftPlan(
  scope: ActionScope,
  work: Work,
  effect: Extract<Effect, { type: "draft-plan" }>,
): Promise<void> {
  const { git } = scope.checkouts;
  const outcomes = work.outcomes as EffectOutcomes;
  const { note } = work.observation;
  const slug = slugFor(note);
  // The checkout is the record's own, the unit's lookup aside: a lane of a
  // fork holds the tree its record leases.
  const tree = work.record.id;
  await git.prepareBranch(note.repo, branchFor(slug), tree);

  const reply = await scope.ports.agent.ask(
    draftPrompt(note, slug, effect.finding),
    git.pathFor(note.repo, tree),
    { workId: work.record.id, step: "draft-plan" },
  );

  const at = scope.ctx.now().toISOString();
  if (reply.run.outcome !== "completed") {
    outcomes.draft = { ok: false, output: reply.run.output, at };
    return;
  }

  // A run that changed nothing is a failure here rather than a success:
  // the machine's notion of "drafted" means the plan is on the remote,
  // because that is what a pull request can be opened against.
  const pushed = await git.commitAndPush(note.repo, branchFor(slug), `docs(plans): ${slug.replace(/-/g, " ")}`, tree);

  outcomes.draft = pushed
    ? { ok: true, output: reply.run.output, at }
    : { ok: false, output: `the agent finished without writing any file\n\n${reply.run.output}`, at };
}

/**
 * The plan is judged where it was written: with a worktree port behind the
 * Git, that is the note's own tree.
 */
export async function checkPlan(scope: ActionScope, work: Work): Promise<void> {
  (work.outcomes as EffectOutcomes).check = await scope.ports["plan-check"].check(
    work.observation.note.repo,
    work.record.id,
  );
}

/**
 * Only this workflow's own half of the fold: the engine has already put the
 * record through `applyPlan`.
 *
 * The repository and the slug are copied off the note rather than produced
 * by an action, so they are folded here. Without them on the record, counting
 * what is in flight for a repository would mean opening every other note to
 * find out what it was about.
 */
export function remember(
  scope: Scope,
  current: PlanRecord,
  outcomes: Record<string, unknown>,
  observation: Observation,
  moved: Moved | null,
): PlanRecord {
  const next = applyOutcomes(current, {
    ...(outcomes as EffectOutcomes),
    repo: observation.note.repo,
    slug: slugFor(observation.note),
  });
  // The call's input is read off the record, and the body is the note's
  // own words, so it is worked out on the move that makes the call.
  return moved?.to === "PR_OPEN" ? { ...next, opening: openingFor(observation.note, scope.checkouts.layout) } : next;
}

/** What the pull request for a note is opened with. */
function openingFor(note: Note, layout: RepoLayout): PullRequestInput {
  const slug = slugFor(note);
  return {
    repo: note.repo,
    branch: branchFor(slug),
    title: pullRequestTitle(slug),
    base: baseBranchFor(layout, note.repo),
    // Written out, unlike the ticket workflow's. There is no ticket behind
    // this one to be the description.
    body: pullRequestBody(note, slug),
  };
}

/** Plans already on their way to a pull request for one repository. */
function inFlightFor(records: Store<PlanRecord>, repo: string, except: string): number {
  return records.all().filter((other) => {
    if (other.id === except) return false;
    return other.repo === repo && IN_FLIGHT.includes(other.state);
  }).length;
}

/** A note the machine wrote about a failure of its own. */
const FAILURE_REPORT = "a tick that failed in";

/**
 * Whether a note is work this workflow should take, or a report of its own.
 *
 * The machine files friction when a tick gives up. That note is written, is
 * counted, and is read by a person — and it is not itself planned: a plan
 * that fails would file another note, which would be planned, which could
 * fail, and the machine would keep opening pull requests about its own
 * reports. What a person can do, a person decides to.
 */
function plannable(note: Note): boolean {
  return !note.source.startsWith(FAILURE_REPORT);
}

import { Plan, act, advance, attemptsIn, looksIn, settled, wait } from "@amykit/core";
import { Observation, Policy } from "./observation.js";
import { PlanRecord } from "./record.js";

export type PlanState = "NOTED" | "DRAFTED" | "CHECKED" | "PR_OPEN" | "DONE" | "DECLINED";
export type Effect =
  | { type: "draft-plan"; finding?: string }
  | { type: "check-plan" }
  | { type: "announce"; text: string };

type Decision = (record: PlanRecord, observation: Observation, policy: Policy) => Plan;

// `PR_OPEN` is a call: the pull-request workflow decides it, and the end it
// reaches says where the note goes.
export const decide = {
  NOTED: planNoted,
  DRAFTED: (record, _observation, policy) => planDrafted(record, policy),
  CHECKED: (record) => planChecked(record),
  DONE: () => settled("the plan is on a pull request, and merging it is somebody else's call"),
  DECLINED: () => settled("nothing was written, and the operator was told why"),
} satisfies Record<Exclude<PlanState, "PR_OPEN">, Decision>;

/**
 * Decides the single next move for one note.
 *
 * Pure on purpose, and short on purpose: nothing in this lifecycle waits on a
 * person. The one thing it holds for is the ceiling on how many plans it may
 * have in flight, and that is a number rather than somebody's answer.
 */
export function plan(record: PlanRecord, obs: Observation, policy: Policy): Plan {
  if (record.state === "PR_OPEN") throw new Error("`PR_OPEN` is a call, decided by the pull-request workflow it calls");
  return decide[record.state](record, obs, policy);
}

function planNoted(record: PlanRecord, obs: Observation, policy: Policy): Plan {
  // Three repositories are the ones this work already lives in, and a note
  // about anything else is a note the operator gets told about instead. It is
  // not a failure and it is not retried: nothing about waiting would make an
  // unwritable repository writable.
  if (!obs.writable) {
    return advance(
      "DECLINED",
      `${obs.note.repo} is not a repository I write plans into`,
      {
        type: "announce",
        text:
          `A note came in about ${obs.note.repo}, which I do not write plans into. ` +
          `It is yours to place: ${obs.note.text}`,
      },
    );
  }

  // Held before anything is drafted rather than before the pull request is
  // opened, because an agent spent on a plan that cannot land is spent for
  // nothing.
  if (obs.plansInFlight >= policy.maxOpenPlansPerRepo) {
    const firstLook = looksIn(record, "NOTED") === 0;
    return wait(
      policy.ceilingBackoffMs,
      `${obs.plansInFlight} plan(s) are already in flight for ${obs.note.repo}`,
      ...(firstLook
        ? ([
            {
              type: "announce" as const,
              text:
                `I am holding a note about ${obs.note.repo}: ` +
                `${obs.plansInFlight} plan(s) of mine are already open there and nobody has ` +
                `read them yet. Merge or close one and I will pick this up.`,
            },
          ] as const)
        : []),
    );
  }

  return advance("DRAFTED", "the note is about a repository I can write a plan into");
}

/**
 * A draft only counts as current if it happened after the last check.
 *
 * Without that, a red check would bounce back into DRAFTED, find the previous
 * successful attempt still recorded, and return to the check forever.
 */
function draftIsCurrent(record: PlanRecord): boolean {
  const draft = record.lastDraft;
  if (!draft) return false;
  if (!record.lastCheck) return true;
  return draft.at > record.lastCheck.at;
}

function checkIsCurrent(record: PlanRecord): boolean {
  const check = record.lastCheck;
  if (!check) return false;
  if (!record.lastDraft) return true;
  return check.at > record.lastDraft.at;
}

/** What the agent is told went wrong, when something did. */
function findingFor(record: PlanRecord): string | undefined {
  if (record.lastCheck && !record.lastCheck.ok && checkIsCurrent(record)) {
    return record.lastCheck.output;
  }
  if (record.lastDraft && !record.lastDraft.ok) return record.lastDraft.output;
  return undefined;
}

function planDrafted(record: PlanRecord, policy: Policy): Plan {
  if (draftIsCurrent(record) && record.lastDraft?.ok) {
    return advance("CHECKED", "the agent wrote a plan, the repository decides if it holds");
  }

  const attempts = attemptsIn(record, "DRAFTED");
  if (attempts >= policy.maxDraftAttempts) {
    return advance(
      "DECLINED",
      `${attempts} draft(s) could not get past the repository's own check`,
      {
        type: "announce",
        text:
          `I could not write a plan ${record.repo ?? "that repository"} would accept, ` +
          `across ${attempts} attempt(s). The last thing it said:\n` +
          `${record.lastCheck?.output ?? record.lastDraft?.output ?? "nothing"}`,
      },
    );
  }

  return act(`draft attempt ${attempts + 1}`, {
    type: "draft-plan",
    finding: findingFor(record),
  });
}

function planChecked(record: PlanRecord): Plan {
  if (!checkIsCurrent(record)) {
    return act("the check has not run against this draft", { type: "check-plan" });
  }

  if (record.lastCheck?.ok) {
    return advance("PR_OPEN", "the repository's own check is green");
  }

  // No effect here on purpose. DRAFTED sees that the check ran after the last
  // draft, so it acts again and picks the finding up as its context. That
  // keeps every retry counted in exactly one place.
  return advance("DRAFTED", "the check is red, back to the agent with the finding");
}

export type { Effect, PlanState } from "./decide.js";

export { attemptsIn, looksIn } from "@amykit/core";
export type { AttemptOutcome, PlanRecord } from "./record.js";

export { DEFAULT_POLICY } from "./observation.js";
export type { Observation, Policy } from "./observation.js";

export { writeNoteFile } from "./note-file.js";
export {
  branchFor,
  planPathFor,
  pullRequestBody,
  pullRequestTitle,
  slugFor,
} from "./plan-file.js";
export { draftPrompt } from "./prompt.js";

export { act, advance, settled, wait } from "@amykit/core";

export { applyNotePlan, applyOutcomes } from "./outcomes.js";
export type { EffectOutcomes } from "./outcomes.js";

export { decide, plan } from "./decide.js";

export { configSchema, plugin } from "./plugin.js";

export type { NewNote, Note, Notes } from "./ports/Notes.js";
export type { PlanCheck } from "./ports/PlanCheck.js";

import fs from "node:fs";
import path from "node:path";
import { NewNote, Note } from "./ports/Notes.js";

/**
 * A note, as the file an editor or a hook would leave.
 *
 * Written here rather than in the store adapter because `amy note` writes one
 * on a machine that will not mount: both callers share one format, and the
 * workflow that reads the directory is the one that owns its vocabulary.
 */
export function writeNoteFile(directory: string, note: NewNote, now: Date): Note {
  fs.mkdirSync(directory, { recursive: true });
  const written: Note = { ...note, id: freeNoteId(directory, now), writtenAt: now.toISOString() };
  fs.writeFileSync(path.join(directory, `${written.id}.md`), noteMarkdown(written), "utf-8");
  return written;
}

function noteMarkdown(note: Note): string {
  return ["---", `repo: ${note.repo}`, `source: ${note.source}`, `written: ${note.writtenAt}`, "---", "", note.text.trim(), ""].join("\n");
}

function freeNoteId(directory: string, now: Date): string {
  const stamp = `note-${now.toISOString().replace(/[:.]/g, "").replace("Z", "")}`;
  const taken = (id: string) => fs.existsSync(path.join(directory, `${id}.md`));
  if (!taken(stamp)) return stamp;
  for (let n = 2; ; n += 1) {
    if (!taken(`${stamp}-${n}`)) return `${stamp}-${n}`;
  }
}

import { Note } from "./ports/Notes.js";

/**
 * A snapshot of the outside world for one note, gathered before deciding.
 *
 * The decision function reads nothing else, so a test can put the machine in
 * any situation by building one of these.
 */
export interface Observation {
  note: Note;
  /** Whether the note is about a repository this install writes plans into. */
  writable: boolean;
  /**
   * Plans this machine is already carrying for that repository: drafted,
   * being checked, or open as a pull request nobody has read yet.
   *
   * Counted across every other note rather than per note, because the thing
   * being rationed is somebody's attention, and that is one pile.
   */
  plansInFlight: number;
  now: Date;
}

export interface Policy {
  /** How many times an agent may try to write a plan the check accepts. */
  maxDraftAttempts: number;
  /**
   * How many plans this machine may have in flight for one repository.
   *
   * A machine that files twelve plans a day into three repositories is not
   * improving them, it is producing a backlog with a robot's name on it. The
   * same argument as the reviewer ceiling, with a different number.
   */
  maxOpenPlansPerRepo: number;
  /** How long to hold while the ceiling is reached. */
  ceilingBackoffMs: number;
}

export const DEFAULT_POLICY: Policy = {
  maxDraftAttempts: 3,
  maxOpenPlansPerRepo: 2,
  ceilingBackoffMs: 60 * 60 * 1000,
};

import { Plan, applyPlan } from "@amykit/core";
import { AttemptOutcome, PlanRecord } from "./record.js";

/**
 * What executing a plan's actions produced.
 *
 * Only the fields its actions actually produced are filled in, so this stays
 * honest about what happened rather than guessing.
 */
export interface EffectOutcomes {
  draft?: AttemptOutcome;
  check?: AttemptOutcome;
  /** Copied off the note on the first look, so the ceiling can be counted. */
  repo?: string;
  slug?: string;
}

/**
 * Folds this workflow's own outcomes into a record.
 *
 * The core folds the state, the attempt count and the history; it cannot fold
 * these, because it does not know what a draft or a check result is. Pure,
 * and the only place a plan record changes shape.
 */
export function applyOutcomes(record: PlanRecord, outcomes: EffectOutcomes): PlanRecord {
  const next: PlanRecord = { ...record };

  if (outcomes.repo) next.repo = outcomes.repo;
  if (outcomes.slug) next.slug = outcomes.slug;
  if (outcomes.draft) next.lastDraft = outcomes.draft;
  if (outcomes.check) next.lastCheck = outcomes.check;

  return next;
}

/** The whole fold for one look: the core's half, then this workflow's. */
export function applyNotePlan(
  record: PlanRecord,
  plan: Plan,
  outcomes: EffectOutcomes,
  now: Date,
): PlanRecord {
  return applyOutcomes(applyPlan(record, plan, now, outcomes), outcomes);
}

import { Note } from "./ports/Notes.js";

/** How many words of the note the slug is allowed to keep. */
const SLUG_WORDS = 8;

/**
 * The name the plan file, the branch and the pull request all take.
 *
 * Derived from the note rather than handed down by anything, because there is
 * no tracker here to own a slug. That makes it this workflow's job to be
 * deterministic about it: the same note produces the same name on the first
 * attempt and on the fourth, so a retry rewrites the draft it started rather
 * than leaving a trail of near-identical files behind.
 */
export function slugFor(note: Note): string {
  const words = note.text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, SLUG_WORDS);

  // A note of pure punctuation still has to land somewhere nameable, and the
  // id is the one thing every note has.
  return words.length > 0 ? words.join("-") : `note-${note.id}`;
}

/** Where the plan is written, relative to the repository's root. */
export function planPathFor(slug: string): string {
  return `plans/${slug}.md`;
}

export function branchFor(slug: string): string {
  return `amy/plan-${slug}`;
}

export function pullRequestTitle(slug: string): string {
  return `docs(plans): ${slug.replace(/-/g, " ")}`;
}

/**
 * What the pull request says for itself.
 *
 * The friction is quoted verbatim and the source is named, because a plan
 * that cannot say what went wrong is a plan nobody can weigh. There is no
 * ticket behind this one to carry that, which is exactly the case this
 * workflow exists for.
 */
export function pullRequestBody(note: Note, slug: string): string {
  return [
    `This plan came out of friction this machine hit.`,
    ``,
    ...note.text.trim().split("\n").map((line) => `> ${line}`),
    ``,
    `Noted by ${note.source} on ${note.writtenAt}.`,
    ``,
    `It adds \`${planPathFor(slug)}\` and its line in \`plans/next-steps.md\`.`,
    `Merging it decides the work is worth doing; nothing here has decided that.`,
  ].join("\n");
}

import path from "node:path";
import { FileQueue } from "@amykit/plugin-file-queue";
import {
  BRANCH_SETTINGS,
  ConfigOf,
  ConfigSchema,
  Harness,
  Notifier,
  Store,
  Worktree,
  call,
  defineOperation,
  defineWorkflow,
  fail,
  optional,
  port,
  scopeOf,
} from "@amykit/core";
import { z } from "zod";
import { plugin as pullRequest } from "@amykit/workflow-pull-request";
import { Effect, decide } from "./decide.js";
import { DEFAULT_POLICY } from "./observation.js";
import { PlanRecord } from "./record.js";
import { Notes } from "./ports/Notes.js";
import { PlanCheck } from "./ports/PlanCheck.js";
import { checkPlan, discover, draftPlan, observe, remember } from "./actions.js";
import { writeNoteFile } from "./note-file.js";
import { branchFor, pullRequestTitle } from "./plan-file.js";

export const configSchema = {
  repos: {
    type: "string[]",
    required: true,
    example: ["Northwind/amy"],
    description: "the repositories a plan may be written into. A note about anything else is handed back to the operator",
  },
  check: {
    type: "record",
    description:
      "the check commands per repository, with a `default` fallback, that judge a plan before it goes anywhere. `sf check` is the whole quality bar in a repository that has one; the plan-check plugin mounts them",
    default: { default: ["sf check"] },
  },
  ...BRANCH_SETTINGS,
  notesDirectory: {
    type: "string",
    description: "where this machine keeps the notes `amy note` writes, relative to the state root. The host sets it; a value here only stands in for one",
    default: "notes",
  },
  queueDirectory: {
    type: "string",
    description: "where this machine keeps the queue `amy note` puts the note on, relative to the state root. The host sets it; a value here only stands in for one",
    default: "queue",
  },
  "policy.maxDraftAttempts": {
    type: "number",
    default: 3,
    description: "how many times an agent may try to write a plan the check accepts before it is handed back",
  },
  "policy.maxOpenPlansPerRepo": {
    type: "number",
    default: 2,
    description:
      "how many plans this machine may carry in flight for one repository. A machine that files twelve plans a day into three repositories is producing a backlog with a robot's name on it, and past this many it holds",
  },
  "policy.ceilingBackoffMs": {
    type: "number",
    default: 60 * 60 * 1000,
    description: "how long a note is held while the plan ceiling is reached",
  },
} satisfies ConfigSchema;

type Settings = ConfigOf<typeof configSchema>;

/**
 * Friction, written down.
 *
 * A file and a queue entry, and nothing else: the operation that captures a
 * complaint has to work on the machine that is complaining, which is exactly
 * the machine whose mount refused. Here it belongs to the workflow that
 * reads what it writes; `amy note` is its command.
 */
const captureNote = defineOperation({
  id: "note-to-plan.capture-note",
  domain: "note-to-plan",
  summary: "Write a piece of friction down, and put it on the queue",
  description:
    "Writes the friction down as a note file and puts it on the queue in one step, against the repository named or the first of `repos`. " +
    "Never drafts the plan itself, and needs no mounted machine.",
  input: z.object({
    text: z.string().describe("what went wrong, in your own words"),
    repo: z.string().optional().describe("the repository it is about; the first of `repos` when unsaid"),
    source: z.string().default("somebody at a keyboard").describe("who noticed"),
  }),
  output: z.object({
    id: z.string().describe("noted"),
    repo: z.string().describe("about"),
  }),
  errors: { "note-to-plan.no_repository": { description: "no repository was named and `repos` lists none" } },
  writes: ["queue"],
  http: { method: "post", path: "/note-to-plan/notes", status: 201 },
  cli: { words: ["note"], positional: ["text"] },
  examples: [{
    summary: "friction in one repository",
    input: { text: "the gate takes two minutes to say nothing", repo: "acme/amy" },
    output: { id: "2026-11-07-the-gate-takes-two-minutes-to-say-nothing", repo: "acme/amy" },
  }],
  async handler({ text, repo, source }, context) {
    const { home, settings } = scopeOf<Settings>(context, "note-to-plan.capture-note");
    const where = repo ?? settings.repos[0];
    if (!where) return fail("note-to-plan.no_repository", "no repository: pass --repo, or list one under `repos`.");

    const now = new Date();
    const written = writeNoteFile(path.join(home, settings.notesDirectory), { repo: where, text, source }, now);
    new FileQueue(path.join(home, settings.queueDirectory)).enqueue({ workId: written.id, reason: "written down by hand" }, now);
    return { id: written.id, repo: where };
  },
});

export const needs = {
  notes: port<Notes>(),
  agent: port<Harness>(),
  "plan-check": port<PlanCheck>(),
  notifier: port<Notifier>(),
  store: port<Store<PlanRecord>>(),
  worktree: optional<Worktree>(),
};

/**
 * A note saved in `PR_OPEN` before it was a call worked out nothing to pass,
 * so it is opened with what its record still says, against the host's default.
 */
function openingAfterUpgrade(work: PlanRecord) {
  const slug = work.slug ?? work.id;
  return { repo: work.repo ?? "", branch: branchFor(slug), title: pullRequestTitle(slug), body: "" };
}

export const plugin = defineWorkflow({
  name: "note-to-plan",
  pluginName: "@amykit/workflow-note-to-plan",
  configSchema,
  policy: DEFAULT_POLICY,
  needs,
  // A project is brief, work and proof; a plan is the work half alone. The
  // friction note a plan comes from already says what the work is, and the
  // plan check the install runs before the pull request is what judges it.
  phases: {
    brief: "the friction note a plan is written from already says what the work is, so no brief phase runs first",
    prove: "the plan check the machine runs on every draft is what judges a plan; the work runs no separate proving phase",
  },
  codeHostWrites: ["open-pull-request"],
  calls: {
    // The pull request is opened by the workflow every shipped workflow
    // shares, against whichever code host the install mounted.
    PR_OPEN: call(pullRequest, {
      input: (work: PlanRecord) => work.opening ?? openingAfterUpgrade(work),
      output: {
        OPENED: (work: PlanRecord, out) => ({ ...work, pullRequestNumber: out.number }),
        REFUSED: (work: PlanRecord, out) => ({ ...work, refusal: out.reason }),
      },
      // The one way into DECLINED that nothing else announces.
      effects: {
        REFUSED: (work: PlanRecord, out) => [{
          type: "announce",
          text:
            `The plan for ${work.repo ?? "the repository"} is written on \`${work.opening?.branch ?? "its branch"}\`, ` +
            `and the code host would not open a pull request for it: ${out.reason}`,
        }],
      },
    }),
  },
  decide,
  operations: [captureNote],
  record: () => ({}),
  discover,
  observe,
  actions: {
    "draft-plan": draftPlan,
    "check-plan": checkPlan,
    // Only worth saying, so a channel that fails never costs the work a move.
    announce: (scope, _work, effect) => scope.announce((effect as Extract<Effect, { type: "announce" }>).text),
  },
  remember,
});

/**
 * A piece of friction, written down.
 *
 * It is not a ticket and does not become one. Nothing resolves it against a
 * tracker, which is the whole point: the machine hit something, and the note
 * is the only record that it did.
 */
export interface Note {
  /** Sortable, so the notes have a stable order without an index. */
  id: string;
  /** The repository the friction is about, as `owner/name`. */
  repo: string;
  /** The friction, in the words of whoever wrote it down. */
  text: string;
  /** Who wrote it: a person at a keyboard, or a tick that failed. */
  source: string;
  writtenAt: string;
}

/** A note as it is written, before anything has been decided about it. */
export type NewNote = Omit<Note, "id" | "writtenAt">;

/**
 * Where the notes are kept.
 *
 * Two ways in and one way out. A note may be written by hand, by a hook, or
 * by this machine when one of its own ticks fails; all three write the same
 * record, and `all()` is what a workflow discovers work from.
 */
export interface Notes {
  write(note: NewNote, now: Date): Note;
  all(): Note[];
  get(id: string): Note | null;
}

import { AttemptOutcome } from "../record.js";

/**
 * The quality bar, which is the repository's own.
 *
 * A plan with no exit condition, or one missing from the ordered list, is
 * refused by the repository a contributor would meet, rather than by a rubric
 * this machine invented for itself. Its output is kept verbatim, because it
 * becomes the finding the agent is sent back with.
 */
export interface PlanCheck {
  /**
   * Runs the check in the work's own tree, when one was isolated for it.
   *
   * The work id is the second half of the address: without a worktree port
   * behind the host's Git it is unused, and the check runs in the shared
   * checkout exactly as it always did.
   */
  check(repo: string, workId?: string): Promise<AttemptOutcome>;
}

import { WorkRecord } from "@amykit/core";
import type { PullRequestInput } from "@amykit/workflow-pull-request";
import type { PlanState } from "./decide.js";

export interface AttemptOutcome {
  ok: boolean;
  /** Whatever the agent or the check said, verbatim, for the next prompt. */
  output: string;
  at: string;
}

/**
 * Everything the machine remembers about one note, persisted between looks.
 *
 * `repo` and `slug` are copied off the note on the first look rather than
 * read from it every time, because the ceiling has to be counted across
 * *other* records without opening every note to find out what each one was
 * about.
 */
export interface PlanRecord extends WorkRecord {
  /** Narrowed from the core's plain label to this workflow's own states. */
  state: PlanState;
  /** The repository the note is about, as `owner/name`. */
  repo?: string;
  /** The name the plan file and the branch both take. */
  slug?: string;
  lastDraft?: AttemptOutcome;
  lastCheck?: AttemptOutcome;
  /** What the pull request is opened with, worked out when the note reaches `PR_OPEN`: its call is passed this. */
  opening?: PullRequestInput;
  pullRequestNumber?: number;
  /** What the code host said when it would not open the pull request. */
  refusal?: string;
}
